const MAX_NODES:usize=51;const MAX_INPUT:usize=39;
const Node=struct{start:usize=0,length:usize=0,suffix:usize=0,child_count:usize=0,children:[MAX_NODES]usize=@splat(0)};
fn codeAt(input:[*]const i64,n:usize,p:usize)i64{return if(p==n) -1 else input[1+p];}
fn put64(output:[*]u8,pos:usize,value:i64)void{const bits:u64=@bitCast(value);for(0..8)|j|output[pos+j]=@truncate(bits>>@intCast(8*j));}
fn suffixLess(input:[*]const i64,n:usize,a:usize,b:usize)bool{var p:usize=0;while(a+p<=n and b+p<=n){const x=codeAt(input,n,a+p);const y=codeAt(input,n,b+p);if(x!=y)return x<y;p+=1;}return a<b;}
export fn suffix_tree_pattern_occurrences(input_opt:?[*]const i64,length:usize,output_opt:?[*]u8,capacity:usize)i64{
 if(input_opt==null or length<3 or length>MAX_INPUT)return -1;const input=input_opt.?;const nr=input[0];if(nr<0 or nr>24)return -1;const n:usize=@intCast(nr);if(length<2+n)return -1;const mr=input[1+n];if(mr<1 or mr>12 or length!=2+n+@as(usize,@intCast(mr)))return -1;const m:usize=@intCast(mr);
 for(0..n)|i|{if(input[1+i]<0 or input[1+i]>127)return -1;}for(0..m)|i|{if(input[2+n+i]<0 or input[2+n+i]>127)return -1;}
 var nodes:[MAX_NODES]Node=@splat(.{});var node_count:usize=1;
 for(0..n+1)|start|{const suffix_len=n+1-start;var off:usize=0;var node:usize=0;while(off<suffix_len){const first=codeAt(input,n,start+off);var slot:usize=0;while(slot<nodes[node].child_count and codeAt(input,n,nodes[nodes[node].children[slot]].start)!=first){slot+=1;}if(slot==nodes[node].child_count){if(node_count>=MAX_NODES)return -1;const leaf=node_count;node_count+=1;nodes[leaf].start=start+off;nodes[leaf].length=suffix_len-off;nodes[leaf].suffix=start;nodes[node].children[nodes[node].child_count]=leaf;nodes[node].child_count+=1;break;}const child=nodes[node].children[slot];var common:usize=0;while(common<nodes[child].length and off+common<suffix_len and codeAt(input,n,start+off+common)==codeAt(input,n,nodes[child].start+common)){common+=1;}if(common==nodes[child].length){off+=common;node=child;continue;}if(node_count>=MAX_NODES)return -1;const split=node_count;node_count+=1;nodes[split].start=nodes[child].start;nodes[split].length=common;nodes[split].children[0]=child;nodes[split].child_count=1;nodes[child].start+=common;nodes[child].length-=common;nodes[node].children[slot]=split;off+=common;node=split;}}
 var node:usize=0;var off:usize=0;var matched=false;while(off<m){const wanted=input[2+n+off];var slot:usize=0;while(slot<nodes[node].child_count and codeAt(input,n,nodes[nodes[node].children[slot]].start)!=wanted){slot+=1;}if(slot==nodes[node].child_count)break;const child=nodes[node].children[slot];var common:usize=0;while(common<nodes[child].length and off+common<m and codeAt(input,n,nodes[child].start+common)==input[2+n+off+common]){common+=1;}if(off+common==m){node=child;matched=true;break;}if(common!=nodes[child].length)break;off+=common;node=child;}
 var starts:[24]usize=@splat(0);var count:usize=0;if(matched){var stack:[MAX_NODES]usize=@splat(0);var top:usize=1;stack[0]=node;while(top>0){top-=1;const x=stack[top];if(nodes[x].child_count==0 and nodes[x].length>0){starts[count]=nodes[x].suffix;count+=1;}for(0..nodes[x].child_count)|j|{stack[top]=nodes[x].children[j];top+=1;}}}
 for(1..count)|i|{const x=starts[i];var j=i;while(j>0 and suffixLess(input,n,x,starts[j-1])){starts[j]=starts[j-1];j-=1;}starts[j]=x;}
 const bytes=8*(1+count);if(output_opt==null or capacity<bytes)return -2;const output=output_opt.?;put64(output,0,@intCast(count));for(0..count)|i|put64(output,8+8*i,@intCast(starts[i]));return @intCast(bytes);
}
